    float wisp = soft(ay - width * (1.0 + 0.25 * fbm(vec2(flowOut * 0.012, p.y * 0.05))), halfWidth * 0.08);
    energy += vec3(0.55, 0.2, 0.9) * wisp * pow(edgeNoise, 2.0) * 0.6 * within * on;
